import math


class SignalGate:
    def __init__(self, coefficients, tag):
        if not isinstance(coefficients, (list, tuple)) or not coefficients:
            raise ValueError("coefficients must be a non-empty sequence")
        if not isinstance(tag, str):
            raise TypeError("tag must be a string")
        self._coefficients = [self._number(v, "coefficient") for v in coefficients]
        self._tag = tag
        self._output = None

    @staticmethod
    def _number(value, name):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{name} must be numeric")
        value = float(value)
        if not math.isfinite(value):
            raise ValueError(f"{name} must be finite")
        return value

    def evaluate(self, samples):
        if not isinstance(samples, (list, tuple)):
            raise TypeError("samples must be a sequence")
        if len(samples) != len(self._coefficients):
            raise ValueError("sample count does not match coefficient count")
        values = [self._number(v, "sample") for v in samples]
        total = sum(weight * (sample / 100.0)
                    for weight, sample in zip(self._coefficients, values))
        if total >= 0:
            factor = math.exp(-total)
            output = 1.0 / (1.0 + factor)
        else:
            factor = math.exp(total)
            output = factor / (1.0 + factor)
        self._output = output
        return output

    def apply_adjustments(self, deltas):
        if not isinstance(deltas, (list, tuple)):
            raise TypeError("deltas must be a sequence")
        if len(deltas) != len(self._coefficients):
            raise ValueError("delta count does not match coefficient count")
        values = [self._number(v, "delta") for v in deltas]
        self._coefficients = [old + delta
                              for old, delta in zip(self._coefficients, values)]

    def get_coefficients(self):
        return self._coefficients

    def get_output(self):
        return self._output

    def get_tag(self):
        return self._tag

